if __name__ == '__main__':
    import random
    rng=random.Random(963)
    positions=[0,1,2]*40
    rng.shuffle(positions)
    for d in D:
        for kind in ('listening','reading'):
            for question in d[kind]['questions']:
                correct=question['options'][question['answer']]
                others=[o for i,o in enumerate(question['options']) if i!=question['answer']]
                rng.shuffle(others)
                new_position=positions.pop()
                others.insert(new_position,correct)
                question['options']=others
                question['answer']=new_position
    p=Path(__file__).parent
    assert len(D)==30
    for d in D:
        for kind in ('listening','reading'):
            assert len(d[kind]['questions'])==2
            for question in d[kind]['questions']:
                assert len(question['options'])==3 and 0<=question['answer']<3
        (p/'scripts'/f'day{d["day"]:02d}.txt').write_text(d['listening']['text'])
    (p/'content.json').write_text(json.dumps(D,ensure_ascii=False,indent=2))
    print(f'{len(D)} days, {sum(len(d[k]["questions"]) for d in D for k in ("listening","reading"))} questions')
